{
  "description": "A stocky quadrupedal creature is shown in right-facing profile against a plain light background, standing on four thick limbs. Its body is covered in dense, shaggy brown fur that is darker on the back and limbs and lighter tan-cream on the muzzle, lower chest and belly. The head is broad with a blunt muzzle, dark eyes, and two small rounded furry ears on top. A single large black horn curves upward from the tip of the nose. The entire dorsal surface from the shoulders to the rump is covered by a large, glossy, dark brown domed shell with a smooth, reflective surface and faint longitudinal ridges on the rear portion. The shell has a scalloped lower edge with a fringe of small rectangular plates and is divided into a smaller anterior shoulder section and a larger posterior section. Four muscular legs end in large paws with dark claws, and a very small furry tail nub is just visible at the rear beneath the shell. No wings, gills, tentacles or additional appendages are visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad and bear-like with dense brown fur, a lighter tan muzzle and lower jaw, dark brown eyes, and a blunt snout, located at the front of the body facing right"
    ,
      "where": "at the front of the body, connected to the neck in front of the shell"
    },
    {
      "part": "horns",
      "looks_like": "one large, black, smooth, sharply pointed horn that curves upward and slightly backward",
      "where": "projecting from the tip of the nose on the front of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears covered in thick brown fur with slightly darker edges",
      "where": "on the top of the head, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred legs with shaggy brown hair, muscular and straight",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large, broad paws with blunt toes and long dark curved claws, the soles are pale brown",
      "where": "at the bottom of each leg, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "very small, short, furry nub, same brown fur as the body",
      "where": "at the extreme rear of the body, just below the overhanging edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large, dome-shaped, hard and glossy dark brown with bright white reflections, smooth on the front section and with faint horizontal ridges on the rear section",
      "where": "covering the entire back from just behind the neck to above the hindquarters, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "the shell is divided into two main plates: a smaller smooth shoulder plate and a larger ridged posterior carapace, with a lower margin of small rectangular marginal plates forming a scalloped fringe",
      "where": "the shoulder plate is over the shoulders, the larger plate covers the mid-back and rump, the marginal plates run along the lower edge of the shell on the side"
    },
    {
      "part": "markings",
      "looks_like": "natural fur shading with no distinct spots or stripes; darker brown on the outer limbs and back, lighter cream on the muzzle, throat, chest and belly; the shell has no color pattern other than shading and glossy highlights",
      "where": "fur color variation over the whole body, shell highlights on the dorsal surface"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
